"""Generate the existing ordinally sorted, LF-only skill index."""

from __future__ import annotations

import argparse
import os
import re
import secrets
import shutil
import subprocess
import sys
from pathlib import Path

from cli_encoding import configure_output
from generate_agent_skill_stubs import require_owned_path

ROOT = Path(__file__).resolve().parents[1]
HEADER = (
    "<!-- DO NOT EDIT - generated by scripts/generate-skills-index.ps1. -->\n"
    "<!-- Regenerate: pwsh -NoProfile -File scripts/generate-skills-index.ps1 -->\n\n"
    "# Skills Index\n\nInvoke these skills for specific tasks.\n"
)
SECTIONS = (
    ("Core Skills (Always Consider)", "Core"),
    ("Performance Skills", "Performance"),
    ("Feature Skills", "Feature"),
)
THREE_FIELDS = re.compile(
    r"<!--\s*trigger:\s*([^|]+)\s*\|\s*([^|]+?)\s*\|\s*(\w+)\s*-->", re.IGNORECASE
)
TWO_FIELDS = re.compile(r"<!--\s*trigger:\s*([^|]+)\s*\|\s*(.+?)\s*-->", re.IGNORECASE)


def skill_sources(directory: Path) -> list[Path]:
    require_owned_path(directory)
    if not directory.is_dir() or directory.is_symlink() or directory.parent.is_symlink():
        raise ValueError(f"Skills directory not found or redirected: {directory}")
    sources = sorted(
        (
            path
            for path in directory.iterdir()
            if path.suffix.casefold() == ".md" and path.name.casefold() != "index.md"
        ),
        key=lambda path: path.name.encode("utf-16-be", errors="surrogatepass"),
    )
    if not sources:
        raise ValueError(f"Skills directory contains no authored Markdown files: {directory}")
    if any(path.is_symlink() or not path.is_file() for path in sources):
        raise ValueError("Skill sources must be physical regular files")
    for source in sources:
        require_owned_path(source)
    return sources


def render(directory: Path, *, verbose: bool = False) -> str:
    entries: list[tuple[str, str, str]] = []
    for source in skill_sources(directory):
        content = source.read_text(encoding="utf-8-sig")
        category = "Feature"
        match = THREE_FIELDS.search(content)
        if match:
            description = match[2].strip()
            category = match[3].strip()
        elif match := TWO_FIELDS.search(content):
            description = match[2].strip()
        else:
            if verbose:
                print(f"[skills-index] No trigger comment in {source.name} - skipping")
            continue
        entries.append((source.stem, description, category))
    entries.sort(key=lambda entry: entry[0].encode("utf-16-be", errors="surrogatepass"))
    result = HEADER
    for title, category in SECTIONS:
        items = [entry for entry in entries if entry[2].casefold() == category.casefold()]
        if not items:
            continue
        result += f"\n## {title}\n\n| Skill | When to Use |\n| --- | --- |\n"
        for name, description, _ in items:
            result += f"| [{name}](./{name}.md) | {description} |\n"
    return result


def publish(path: Path, content: str) -> None:
    if path.is_symlink():
        raise ValueError(f"Refusing a redirected index destination: {path}")
    if path.exists() and (not path.is_file() or not path.stat().st_mode & 0o222):
        raise ValueError(f"Refusing a non-writable regular index destination: {path}")
    temporary = path.with_name(f".skills-index-{secrets.token_hex(16)}")
    owned = False
    try:
        stream = temporary.open("xb")
        owned = True
        with stream:
            stream.write(content.encode("utf-8"))
        if path.is_file():
            shutil.copymode(path, temporary)
        temporary.replace(path)
    finally:
        if owned:
            temporary.unlink(missing_ok=True)


def check_index(root: Path, expected: bytes) -> None:
    path = root / ".llm/skills/index.md"
    require_owned_path(path)
    if not path.is_file() or path.read_bytes() != expected:
        raise ValueError(".llm/skills/index.md is out of date or missing")
    git = shutil.which("git")
    if git is None:
        raise ValueError("Git is required to verify the committed skills index")
    environment = {
        **{
            name: value for name, value in os.environ.items() if not name.upper().startswith("GIT_")
        },
        "GIT_TERMINAL_PROMPT": "0",
        "GIT_NO_REPLACE_OBJECTS": "1",
    }

    def query(arguments: list[str]) -> bytes:
        result = subprocess.run(  # noqa: S603 - fixed read-only Git queries without inherited repository overrides.
            [git, "-C", str(root), *arguments],
            env=environment,
            capture_output=True,
            check=False,
            timeout=60,
        )
        if result.returncode:
            raise ValueError(
                f"Skills index Git check failed: {result.stderr.decode('utf-8', errors='replace').strip()}"
            )
        return result.stdout

    top = Path(query(["rev-parse", "--show-toplevel"]).decode("utf-8").strip()).resolve()
    if top != root.resolve():
        raise ValueError("Skills index check requires the selected repository root")
    query(["ls-files", "--error-unmatch", "--", ".llm/skills/index.md"])
    if query(["status", "--porcelain", "--", ".llm/skills/index.md"]):
        raise ValueError(".llm/skills/index.md is out of date or uncommitted")


def main(arguments: list[str] | None = None) -> int:
    configure_output()
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--repo-root", type=Path, default=ROOT)
    parser.add_argument("--output-path", type=Path)
    parser.add_argument("--stdout", action="store_true")
    parser.add_argument("--check", action="store_true")
    parser.add_argument("--verbose", action="store_true")
    args = parser.parse_args(arguments)
    if args.check and (args.stdout or args.output_path):
        parser.error("--check cannot be combined with --stdout or --output-path")
    try:
        content = render(args.repo_root / ".llm/skills", verbose=args.verbose)
        if args.check:
            check_index(args.repo_root, content.encode("utf-8"))
            print("Skills index is up-to-date.")
        elif args.stdout:
            sys.stdout.write(content)
        else:
            output = args.output_path or args.repo_root / ".llm/skills/index.md"
            publish(output, content)
            if args.verbose:
                print(f"[skills-index] Wrote {output}")
    except (OSError, ValueError, subprocess.SubprocessError) as error:
        print(f"[skills-index] ERROR: {error}")
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
